import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";import"./chunks/assets.ByxXdwmG.js";var i=JSON.parse(`{"title":"Jevの接続設定と利用状況","description":"","frontmatter":{},"headers":[],"relativePath":"guides/jev.md","filePath":"guides/jev.md","lastUpdated":1793681056000}`),a={name:`guides/jev.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="jevの接続設定と利用状況" tabindex="-1">Jevの接続設定と利用状況 <a class="header-anchor" href="#jevの接続設定と利用状況" aria-label="Permalink to “Jevの接続設定と利用状況”">​</a></h1><p>対象サイトを選び、左メニューの「Jev連携」を開きます。サイト管理者とSuperuserだけが利用できます。編集者・閲覧者にはキー設定・利用記録を公開しません。</p><h2 id="サイトごとのキーを設定する" tabindex="-1">サイトごとのキーを設定する <a class="header-anchor" href="#サイトごとのキーを設定する" aria-label="Permalink to “サイトごとのキーを設定する”">​</a></h2><p>Jev APIキーはサイトIDごとに登録します。インスタンス共通キーは使いません。新しいサイトと、以前に共通キーを使っていたサイトは「APIキー未設定」になります。</p><table tabindex="0"><thead><tr><th>使用するキー</th><th>動作</th></tr></thead><tbody><tr><td>サイト専用キー</td><td>このサイトIDに保存したJev APIキーを使う</td></tr><tr><td>Jevの利用を停止</td><td>このサイトのJev判定を停止し、保存済みキーを削除する</td></tr></tbody></table><ol><li>「サイト専用キー」を選ぶ。</li><li>「新しいサイト専用APIキー」へ入力する。</li><li>「Jev接続設定を保存」を押して確認する。必要に応じてパスキーで本人確認する。</li></ol><p>保存済みの値は再表示しません。再度開くと空欄になり、「保存済み」とだけ表示されます。既に専用キーがある場合、空欄で保存すると現在値を保持します。新しい値を入力すると置き換わります。保存操作ではJevへの接続・有効性確認・課金を行いません。</p><p>専用キーの保存には、環境管理者による<a href="./../operations/jev-keys">暗号化キーの初期設定</a>が必要です。未設定の場合は案内が表示されます。</p><div class="warning custom-block"><p class="custom-block-title">接続モードの切り替え</p><p>利用停止へ変更すると、保存済みサイトキーを削除します。元に戻す場合はキーを入力し直してください。Jev側のキーを失効する操作ではありません。</p></div><p>キーが未設定・失効・復号不能の場合は判定を保留します。他サイトのキーは使いません。キー変更前から進行している要求は取り消せません。</p><p>以下はテスト用の設定による画面例です。実際のAPIキーは表示していません。</p><p><img src="/jev-personalization/images/jev-connection.png" alt="サイト専用キーの接続設定" width="1280" height="928"></p><h2 id="設定状況の通知" tabindex="-1">設定状況の通知 <a class="header-anchor" href="#設定状況の通知" aria-label="Permalink to “設定状況の通知”">​</a></h2><p>選択中サイトの管理画面には、未設定や停止の内容と対応先を表示します。編集者・閲覧者も不足内容を確認できますが、キーの登録・変更と利用記録の閲覧はサイト管理者・Superuserだけが行えます。</p><ul><li><strong>APIキー未設定</strong>：このサイトの「Jev連携」からキーを登録してください。</li><li><strong>暗号化設定がない・キーを読み出せない</strong>：環境管理者にJEV_KEYRINGを確認してもらいます。</li><li><strong>Jevの利用を停止中</strong>：再開する場合は専用キーを入力し直します。</li><li><strong>メタデータ送信が無効・配信中の施策なし</strong>：サイト設定と施策一覧で確認します。</li></ul><p>状態はサイト切り替え・ページ再読み込み・保存後に更新します。SDKタグの設置や利用者の同意は、この通知だけでは確認できません。「動作確認」から確認してください。キーの保存済み表示は、Jev側の有効性や残高を保証しません。確認のためのJev問い合わせは行いません。URLだけで結論が出る判定は、Jev条件を含む施策でもキーなしで利用できます。未確定のJev条件が残る場合は、サイトのキー登録が必要です。Previewの固定値判定は実Jevへ接続しません。</p><p><img src="/jev-personalization/images/site-readiness.png" alt="未設定の内容を閲覧者にも表示する例。キーの変更はサイト管理者へ依頼します。" width="390" height="1021"></p><h2 id="利用状況を見る" tabindex="-1">利用状況を見る <a class="header-anchor" href="#利用状況を見る" aria-label="Permalink to “利用状況を見る”">​</a></h2><p>「利用状況」を開き、過去7日・30日・90日を選んで「更新」を押します。集計はUTC日単位です。日別件数と最近100件の結果・モデル名・HTTP status・遅延・キーの種類を表示します。廃止前の共通キーによる記録は「共通キー（廃止済み）」と表示し、新しい呼び出しはサイト専用キーだけを使います。キーの変更前後を含むこのサイト全体の記録です。自動ポーリングは行いません。</p><table tabindex="0"><thead><tr><th>表示</th><th>意味</th></tr></thead><tbody><tr><td>呼び出し開始</td><td>Jev APIの呼び出し開始処理を記録した数</td></tr><tr><td>正常応答</td><td>HTTPの応答と基本的なデータ形式が正常だった数。表示条件に合致した数ではない</td></tr><tr><td>エラー</td><td>HTTP失敗・タイムアウト・通信失敗・応答形式不正</td></tr><tr><td>結果未確定</td><td>処理中・処理の中断・結果の保存失敗のいずれかで、結果が確定していない記録</td></tr></tbody></table><p>ブラウザからの判断要求がすべてJevへ進むわけではありません。条件未達、予算超過、キー未設定、停止、Preview/local-reviewの固定判定、配信前の強制プレビューは件数に含みません。新機能を導入する前の履歴も表示しません。</p><p>画面例の件数・結果・モデル・遅延は、UI検証用に作成した人工データです。Jevの実測ではありません。</p><p><img src="/jev-personalization/images/jev-usage.png" alt="Jev利用状況の画面例" width="1280" height="1306"></p><h2 id="件数と課金の違い" tabindex="-1">件数と課金の違い <a class="header-anchor" href="#件数と課金の違い" aria-label="Permalink to “件数と課金の違い”">​</a></h2><p>送信開始前に記録し、応答後に結果を更新します。その間の中断では、実際の送信前でも開始行が残ったり、送信済みでも未確定になったりします。Jev側が受信した件数・課金件数・金額を保証するカウンターではありません。</p><p><strong>課金や消費量はJev（TypeSafe）側で確認してください。</strong> 失敗した要求の課金有無も提供元のルールに従います。正常応答は購入・施策成功を意味せず、遅延はJevのHTTP処理時間で、画面表示までの全時間ではありません。</p><p>費用上限と同時実行数は、専用キーを使う場合もインスタンス全体で共有します。サイト別の予算上限は今回の機能に含みません。</p><h2 id="記録されないもの" tabindex="-1">記録されないもの <a class="header-anchor" href="#記録されないもの" aria-label="Permalink to “記録されないもの”">​</a></h2><p>キーの値・断片、閲覧者ID・IP・URL・履歴、state、questions、回答、確率、要求/応答本文は残しません。保存対象は呼び出しの運用メタデータだけです。記録は最大90日の範囲で表示し、古い行は利用・閲覧のタイミングで削除します。バックアップ中の記録は別の保持方針で管理します。</p><p>Previewの固定判定では、キーを入力しても実際の有効性やJevとの接続は確認できず、利用件数は増えません。実接続を試す場合は環境管理者と確認し、課金される要求として別途実施してください。</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};